SEED='demo'
W="await T.w(450);"
CASES=[
 ('NAV-01','Navigation','Every main page opens and shows its title',"(async()=>{const ids=['pgToday','pgHabits','pgExp','pgAI','pgJr','pgTasks','pgStats','pgSet'],bad=[];for(const id of ids){showTab(id);await T.w(250);if(T.page()!==id||!T.q('#'+id+' h1'))bad.push(id);}return T.ok(!bad.length,bad.length?'failed: '+bad:'8 pages')})()"),
 ('NAV-02','Navigation','Bottom bar shows Home, Habits, Create, Money, AI on phones',"(()=>{const t=T.qa('#tabbar .tab').filter(x=>T.vis(x)).map(x=>x.innerText.trim());return T.ok(t.join(',')==='Home,Habits,Create,Money,AI'||t.join(',')==='Home,Habits,,Money,AI',t)})()"),
 ('NAV-03','Navigation','Create (+) opens the action menu with all entries',"(async()=>{showTab('pgToday');T.click('#tabbar .navFab');"+W+"const a=T.qa('#actionSheet [data-add-action]').filter(x=>T.vis(x)).map(x=>x.getAttribute('data-add-action'));return T.ok(sheetOpen==='actionSheet'&&['habit','task','expense','journal','mood','workout'].every(k=>a.includes(k)),a)})()"),
 ('NAV-04','Navigation','Create menu: each entry opens the right screen',"(async()=>{const exp={habit:'addSheet',task:'taskSheet',expense:'expSheet',journal:'jrSheet',mood:'moodSheet'},bad=[];for(const k in exp){closeSheet();"+W+"T.click('#tabbar .navFab');"+W+"T.click('[data-add-action=\"'+k+'\"]');await T.w(700);if(sheetOpen!==exp[k])bad.push(k+'->'+sheetOpen);}closeSheet();"+W+"T.click('#tabbar .navFab');"+W+"T.click('[data-add-action=\"workout\"]');await T.w(600);const wk=T.vis('#wkModule');return T.ok(!bad.length&&wk,(bad.join(', ')||'all open')+' | workout module: '+wk)})()"),
 ('NAV-05','Navigation','Android back closes a sheet, then returns to Home',"(async()=>{showTab('pgTasks');openTask(null);"+W+"const a=handleAndroidBack();"+W+"const s1=!sheetOpen;const b=handleAndroidBack();"+W+"return T.ok(a&&s1&&b&&T.page()==='pgToday','closed sheet:'+s1+' page:'+T.page())})()"),
 ('NAV-06','Navigation','Android back on Home asks before leaving',"(async()=>{showTab('pgToday');closeSheet();"+W+"const r=handleAndroidBack();return T.ok(r===false||!!document.querySelector('.exitDlgWrap'),'returned '+r)})()"),
 ('NAV-07','Navigation','Global search finds a habit, a journal entry, a task and a transaction',"(async()=>{const h=state.habits[0].name.slice(0,5),j=(state.jr[0].title||'').slice(0,5),t=state.tasks.find(x=>!x.virtualHabit).title.slice(0,5),x=(state.tx.find(x=>x.payee)||{}).payee.slice(0,4);const r={};for(const [k,q] of [['habit',h],['journal',j],['task',t],['tx',x]]){gSearchRun(q);r[k]=T.qa('#gSearchOut [data-gs]').length;}return T.ok(Object.values(r).every(n=>n>0),r)})()"),
 ('NAV-08','Navigation','Search with no match shows a friendly empty message',"(()=>{gSearchRun('zzqxv');const t=T.q('#gSearchOut').textContent;return T.ok(/no|nothing/i.test(t),t.slice(0,60))})()"),
 ('NAV-09','Navigation','Search result opens the item',"(async()=>{gSearchRun(state.jr[0].title.slice(0,6));const b=T.q('#gSearchOut [data-gs^=\"jr:\"]');if(!b)return T.ok(false,'no result');b.click();await T.w(700);return T.ok(T.q('#jrReadSheet').classList.contains('open'),'reader open')})()"),
 ('HOME-01','Home','Home shows Spaces, Today, Next and At a glance',"(()=>{homeMoment=()=>'day';showTab('pgToday');renderHome();const l=T.qa('#homeOverview .sectLbl').map(x=>x.textContent.trim().toLowerCase());return T.ok(['spaces','today'].every(k=>l.some(x=>x.includes(k))),l)})()"),
 ('HOME-02','Home','Today ring matches habits done / scheduled',"(()=>{const d=habitsDoneOn(today());const t=T.q('#homeOverview').innerText;return T.ok(new RegExp(d.done+'\\\\s*/\\\\s*'+d.due).test(t),d)})()"),
 ('HOME-03','Home','Morning layout leads with Top 3 today',"(()=>{homeMoment=()=>'morning';renderHome();const s=T.q('[data-sec=top3]');homeMoment=()=>'day';renderHome();return T.ok(!!s,'top3 shown')})()"),
 ('HOME-04','Home','Evening layout shows the wrap-up and daily review',"(()=>{homeMoment=()=>'evening';renderHome();const t=T.q('#homeOverview').innerText;homeMoment=()=>'day';renderHome();return T.ok(/wrap|review/i.test(t),t.slice(0,80))})()"),
 ('HOME-05','Home','Every Spaces tile opens its destination',"(async()=>{const tiles=T.qa('.hmSpaceGrid button').filter(x=>T.vis(x));const r=[];for(const i in tiles){showTab('pgToday');renderHome();await T.w(200);const b=T.qa('.hmSpaceGrid button').filter(x=>T.vis(x))[i];const n=b.textContent.trim();b.click();await T.w(600);r.push(n+':'+(sheetOpen||T.page()||'')+(T.vis('#wkModule')?'+wk':''));try{closeSheet()}catch(e){}const wk=document.getElementById('wkModule');if(wk)wk.classList.remove('on');document.querySelectorAll('.proModal').forEach(e=>e.remove());}return T.ok(r.length>=6&&!r.some(x=>/:pgToday$/.test(x)&&!/Review|Sleep|Vault/.test(x)),r)})()"),
 ('HOME-07','Home','Scope trim: no Sleep/Review spaces, no sleep gate, Today tiles are Tasks/Mood/Money',"(async()=>{homeMoment=()=>'day';showTab('pgToday');renderHome();await T.w(300);const sp=T.qa('.hmSpaceGrid button').map(b=>b.textContent.trim());const tiles=T.qa('.hmG3t').map(b=>b.getAttribute('data-hmg'));return T.ok(!sp.includes('Sleep')&&!sp.includes('Review')&&tiles.join()==='tasks,mood,money'&&!T.vis('#sleepGate'),sp+' | '+tiles)})()"),
 ('HOME-06','Home','Sunday weekly recap renders with stats',"(()=>{const h=weeklyRecapHTML(new Date());return T.ok(/habits done/.test(h),h.replace(/<[^>]+>/g,' ').replace(/\\\\s+/g,' ').slice(0,90))})()"),
]
